\label{defweak}
Assume that (AOP) and (AG) hold, and let \(\rho>-1\). A function
\(u\in C([0,\infty);V_1)\) with \(u_t\in C([0,\infty);V_0)\) satisfying
\((u(0);u_t(0))=(u_0;u_1)\) is called a \textit{global strong solution}
to Problem \eqref{abstract} on \([0,\infty)\) if:
\begin{description}
\item[(i)] \(u\in W^{1,\infty}(0,T;V_1)\) and \(u_t\in W^{1,\infty}(0,T;V_0)\)
for all \(0<T<\infty\);
\item[(ii)] Equation \eqref{abstract} holds in \(V_0\) for almost every
\(t\in[0,\infty)\).
\end{description}

\label{continuity}
Assume that \(\rho>-1\), and let
\[
l(v):=\|v\|^{\rho}v,\qquad v\in V_0.
\]
Then \(l:V_0\to V_0\) is monotone and semicontinuous. More precisely:
\begin{enumerate}
\item \((l(u)-l(v),u-v)\geq0\) for all \(u,v\in V_0\);
\item for all \(u,v,w\in V_0\), the map \(\lambda\mapsto(l(u+\lambda v),w)\) is continuous from \(\mathbb{R}\) to \(\mathbb{R}\).
\end{enumerate}

\label{lemI1}
Assume that (AOP) and (AG) hold, and define
\begin{equation}\label{I1t}
I_1(t):=-\left(u_t(t),\int_{0}^{t}g(t-s)(u(t)-u(s))ds\right).
\end{equation}
For any \(\varepsilon_1>0\), there exists a constant \(\hat C(\varepsilon_1)>0\), depending only on \(\varepsilon_1\) and \(\lambda_1\), such that, for any \(t\geq t_0\),
\begin{align}\label{I1esti}
\frac{d}{dt}I_1(t)
&\leq-\frac{G_0}{4}\|u_t(t)\|^2+\varepsilon_1\left\|A^{\frac12}u(t)\right\|^2+C\|u_t(t)\|^{2\rho+2}\notag\\
&\quad+\hat C(\varepsilon_1)M(\delta)\int_{0}^{t}K_\delta(t-s)\left\|A^{\frac12}u(t)-A^{\frac12}u(s)\right\|^2ds\notag\\
&\quad-\frac{g(0)}{\lambda_1G_0}\int_{0}^{t}g'(t-s)\left\|A^{\frac12}u(t)-A^{\frac12}u(s)\right\|^2ds,
\end{align}
where \(t_0\), \(G_0\), \(\lambda_1\), \(K_\delta\), and \(M(\delta)\) are given in \eqref{existencet0}, \eqref{G0}, \eqref{basis}, \eqref{K}, and \eqref{M}, respectively, and \(C>0\) is a constant depending only on \(\rho\).

\label{lemI2}
Assume that (AOP) and (AG) hold. For any \(t\geq0\),
\begin{equation}\label{I2}
\begin{split}
\frac{d}{dt}I_2(t)
&\leq-\frac{\mu_0}{2}\|A^{\frac12}u(t)\|^2+\|u_t(t)\|^2+C\|u_t(t)\|^{2\rho+2}\\
&\quad+CM(\delta)\int_{0}^{t}K_{\delta}(t-s)\left\|A^{\frac12}u(t)-A^{\frac12}u(s)\right\|^2ds,
\end{split}
\end{equation}
where
\[
I_2(t):=\left(u_t(t),u(t)\right),
\]
and \(\mu_0\), \(K_\delta\), and \(M(\delta)\) are given in \eqref{mu_0}, \eqref{K}, and \eqref{M}, respectively. The constant \(C>0\) depends only on \(\mu_0,\lambda_1\).

\label{lem2.4}
Assume that (AOP) and (AG) hold. The functional
\begin{align}
I_3(t):=\int_{0}^{t}G(t-s)\left\|A^{\frac12}u(s)\right\|^2ds,\label{I3t}
\end{align}
with \(G(t)=\int_{t}^{\infty}g(s)ds\) defined in \eqref{G}, satisfies
\begin{align}
\frac{d}{dt}I_3(t)=-\int_{0}^{t}g(t-s)\left\|A^{\frac12}u(s)\right\|^2ds+G_0\left\|A^{\frac12}u(t)\right\|^2,\label{I3d}
\end{align}
and
\begin{align}
\frac{d}{dt}I_3(t)\leq-\frac12\int_{0}^{t}g(t-s)\left\|A^{\frac12}u(t)-A^{\frac12}u(s)\right\|^2ds+3G_0\left\|A^{\frac12}u(t)\right\|^2,\label{I3}
\end{align}
where \(G_0\) is given in \eqref{mu_0}.

\label{lem2.5}
Assume that (AOP) and (AG) hold. The functional
\[
I_4(t):=M(\delta)\left(\delta\int_{0}^{t}G(t-s)\|A^{\frac12}u(s)\|^2ds+E(t)\right)
\]
satisfies
\begin{align}
\frac{d}{dt}I_4(t)\leq-\frac12M(\delta)\int_{0}^{t}K_{\delta}(t-s)\left\|A^{\frac12}u(t)-A^{\frac12}u(s)\right\|^2ds\notag\\
+3G_0\delta M(\delta)\|A^{\frac12}u(t)\|^2,\label{I4}
\end{align}
where \(E\) is defined in \eqref{energy}, and \(G_0\), \(K_\delta\), and \(M(\delta)\) are given in \eqref{mu_0}, \eqref{K}, and \eqref{M}, respectively.
